DELETE FROM material WHERE id IN ('76a06b4c-6e22-508e-a164-cee4717424e5','cfc019e9-7612-5f31-b5a7-0e3a3669c557','805e24bf-d16c-5f4b-ae8f-33c90b1cb8fa','4183d3e6-0a8e-5ce3-9c68-ead4de9eefac','2f8d2fe7-6b36-5c57-9abb-315bc92a5ae3','13c81077-de9d-5f33-a39d-74219e67da00','5976f255-0990-5c3a-a06a-4ff57c60e28d','c6ead78b-3d25-5a47-bb1e-dbf83218daa9','3013f758-0313-5e7c-99a3-168a429c4baf','5e27392b-3130-5f90-8d3c-fb6f044ac526','bd971d2a-64c1-5747-9aea-3584df7a183e','597b38c5-99a6-5c74-83b7-b5f82aa12e8d','dfc199a4-daba-5208-8c6f-596e4dcf1c3f','136cdd54-3804-52cb-b437-52e65b21733a','59138e28-e0e4-5d91-ba2c-dd10f88fcf0a','4b5289fb-aff1-5824-90af-7d7cb76738df','5127e6ab-c50a-56b4-97c0-236ef96534ab','dd8cd487-4c8c-586c-8442-7f45e5fe47be','1691315f-47eb-5f94-ad8b-0d311828cc1c','f2809a61-24cb-55f4-8f2c-ba7ea0229977','c855fd1c-62d4-5d80-b711-9f416b599a68','d62e538a-e4db-5e51-a670-b46981fe9e03','a158ca69-0fbe-569c-9ca7-815dd2c08907','0b9df454-929a-55f1-bc00-9c680c6f4efe','286d866e-14e8-5041-b715-0e96190b5a6a','b67a82de-27f5-5b26-b296-4013de244b62','8f1f0903-606b-5128-96c2-0511b6fb1405','2a853c15-6775-5dbc-8e10-6709f6e080e9');

DELETE FROM dance_figure_step WHERE dance_figure_step_set_id IN (SELECT ss.id FROM dance_figure_step_set ss JOIN dance_figure f ON f.id = ss.dance_figure_id JOIN dance_type t ON t.id = f.dance_type_id WHERE (t.name, f.name) IN (($q$Cha Cha$q$,$q$Hockey Stick$q$),($q$Foxtrot$q$,$q$Feather Step$q$),($q$Rumba$q$,$q$Fan$q$),($q$Tango$q$,$q$Closed Promenade$q$),($q$Waltz$q$,$q$Reverse Turn$q$),($q$Waltz$q$,$q$Whisk$q$)) AND f.name <> 'Natural Turn');
DELETE FROM dance_figure_step_set ss USING dance_figure f, dance_type t WHERE f.id = ss.dance_figure_id AND t.id = f.dance_type_id AND (t.name, f.name) IN (($q$Cha Cha$q$,$q$Hockey Stick$q$),($q$Foxtrot$q$,$q$Feather Step$q$),($q$Rumba$q$,$q$Fan$q$),($q$Tango$q$,$q$Closed Promenade$q$),($q$Waltz$q$,$q$Reverse Turn$q$),($q$Waltz$q$,$q$Whisk$q$)) AND NOT (t.name = 'Viennese Waltz' AND f.name = 'Natural Turn') AND NOT EXISTS (SELECT 1 FROM dance_figure_step x WHERE x.dance_figure_step_set_id = ss.id);
UPDATE dance_figure f SET notes = NULL, starting_position = CASE WHEN f.starting_position = s.sp THEN NULL ELSE f.starting_position END, ending_position = CASE WHEN f.ending_position = s.ep THEN NULL ELSE f.ending_position END, version = f.version + 1 FROM dance_type t, (VALUES ($q$Waltz$q$,$q$Natural Turn$q$,$q$Facing Diagonal Wall$q$,$q$Backing Diagonal Centre$q$,$q$Rise at the end of 1, maintained on 2, lowering at the end of 3. Body turn begins on 1 with CBM and the left side stays long through the turn. Keep the head weight to the left and the topline stretched; do not drop the head forward as you rise.$q$),($q$Waltz$q$,$q$Reverse Turn$q$,$q$Facing Diagonal Centre$q$,$q$Backing Diagonal Wall$q$,$q$Mirror of the Natural Turn: left side of the lady stays long, man leads the turn from the torso, not the arms. Sway to the left on 2, no sway on 1 and 3. Lower on the end of 3 through the ankles and knees.$q$),($q$Waltz$q$,$q$Whisk$q$,$q$Facing Diagonal Wall$q$,$q$Promenade Position$q$,$q$Step 3 is crossed behind with the toe turned out and the head already moving to the right. Rise on 2, lower after 3. Keep the frame closed until the lady opens to Promenade Position, then show a clear lengthening of the left side.$q$),($q$Waltz$q$,$q$Hesitation Change$q$,$q$Facing Diagonal Wall$q$,$q$Facing Diagonal Wall$q$,$q$Hesitation on step 3: the weight is taken on the foot but the body keeps rising, so the lowering is delayed to the end of count 3. Do not let the head fall as the rise settles.$q$),($q$Waltz$q$,$q$Telemark (Closed Telemark)$q$,$q$Facing Diagonal Centre$q$,$q$Facing Diagonal Wall$q$,$q$Heel turn on step 2 with the man turning on his left heel; keep the shoulders level and the head weight left. Rise through steps 2 and 3.$q$),($q$Waltz$q$,$q$Fallaway Reverse and Slip Pivot$q$,$q$Facing Diagonal Centre$q$,$q$Backing Diagonal Wall$q$,$q$Fallaway with the head to the left, open topline with the lady's head turned strongly right. The slip pivot needs the man to stay compact and not over-rotate on the backward step.$q$),($q$Tango$q$,$q$Closed Promenade$q$,$q$Facing Diagonal Wall$q$,$q$Promenade Position$q$,$q$No rise and fall: the knees stay slightly flexed and the walk is flat. The head snap to Promenade Position is quick and sharp on the &. Keep the frame compact and the lady's left side long without lifting the ribcage.$q$),($q$Tango$q$,$q$Progressive Link$q$,$q$Facing Diagonal Wall$q$,$q$Facing Diagonal Wall$q$,$q$Staccato action: the foot is placed slightly across and the knee reaches before the weight arrives. Avoid stepping heavily; think of a stalking cat.$q$),($q$Tango$q$,$q$Natural Twist Turn$q$,$q$Facing Diagonal Centre$q$,$q$Facing Diagonal Wall$q$,$q$The man stays on his supporting foot while the lady twists around him. Maintain the contra-body position and a stable topline; the head must not drop during the twist.$q$),($q$Tango$q$,$q$Open Reverse, Lady Outside (Open Finish)$q$,$q$Facing Diagonal Centre$q$,$q$Facing Diagonal Wall$q$,$q$Sharp CBM on step 1, ending with the lady outside. Slow-slow-quick-quick-slow rhythm; the head snap on the quick steps is small and controlled.$q$),($q$Foxtrot$q$,$q$Feather Step$q$,$q$Facing Diagonal Wall$q$,$q$Facing Diagonal Wall$q$,$q$Slow-quick-quick. Heel lead on step 1 with a long smooth stride; step 3 outside partner in CBMP. Rise gradually from the end of 1 and lower on 3 without a bounce. Keep the head weight to the left.$q$),($q$Foxtrot$q$,$q$Reverse Turn$q$,$q$Facing Diagonal Centre$q$,$q$Backing Diagonal Wall$q$,$q$Heel turn on step 3, with the man's left shoulder leading. Keep the body flight smooth and the topline stretched upwards; the head should stay left and not dip as the lowering happens.$q$),($q$Foxtrot$q$,$q$Three Step$q$,$q$Facing Diagonal Wall$q$,$q$Facing Diagonal Wall$q$,$q$Three steps with the long-short-short timing. Heel lead, smooth travel. A common fault is rushing step 3; stay on the foot until the end of the count.$q$),($q$Foxtrot$q$,$q$Natural Weave$q$,$q$Facing Diagonal Wall$q$,$q$Facing Diagonal Wall$q$,$q$The weave is a flow of curved, outside-partner steps on a long arc. The man must allow the lady to curve around him with soft knees and a continuous swing.$q$),($q$Quickstep$q$,$q$Natural Turn (at a Corner)$q$,$q$Facing Diagonal Wall$q$,$q$Facing Diagonal Wall$q$,$q$Fast travelling turn on a corner. Use a lot of foot and ankle action and a strong swing into the diagonal. Keep the head up and the left side long to control speed.$q$),($q$Quickstep$q$,$q$Progressive Chasse$q$,$q$Facing Diagonal Wall$q$,$q$Facing Diagonal Wall$q$,$q$Slow-quick-quick-slow with the chasse steps closing lightly. Rise on the quick steps without bouncing, and lower on the last slow.$q$),($q$Quickstep$q$,$q$Running Right Turn$q$,$q$Facing Diagonal Wall$q$,$q$Facing Diagonal Wall$q$,$q$A curved running finish with four small quick steps; the body continues to turn right. The drive for the finish comes from the standing foot, not from hopping.$q$),($q$Quickstep$q$,$q$Quick Open Reverse$q$,$q$Facing Diagonal Centre$q$,$q$Facing Diagonal Wall$q$,$q$Quick open reverse turn with the lady outside partner at the end. Maintain the frame and avoid taking the lady's weight with the arms.$q$),($q$Viennese Waltz$q$,$q$Reverse Turn$q$,$q$Facing Diagonal Centre$q$,$q$Backing Diagonal Wall$q$,$q$Six steps at a fast tempo, with rise on 1, 3, 4 and 6 and the feet closing on 3 and 6. Keep the left side long as the turn travels round the floor; do not drop the head as the speed builds.$q$),($q$Viennese Waltz$q$,$q$Reverse Fleckerl$q$,$q$Backing Line of Dance$q$,$q$Backing Line of Dance$q$,$q$Turning on the spot with small steps. Heel turns by the man while the lady travels around him; keep the head weight left and the body compact.$q$),($q$Cha Cha$q$,$q$Hockey Stick$q$,$q$Open Position$q$,$q$Open Position$q$,$q$A fan followed by a lock-step type finish. The man leads the lady into a fan position then brings her through with a hockey stick curve. Cuban hip action on the forward walks and a clear Cha Cha Cha rhythm 2 3 4&1.$q$),($q$Cha Cha$q$,$q$Fan$q$,$q$Closed Position$q$,$q$Fan Position$q$,$q$The man steps back with a check on the left foot while the lady turns across the line of dance into fan position. Hold the position slightly stronger than the previous step.$q$),($q$Cha Cha$q$,$q$Alemana Development (R to R Hand Hold)$q$,$q$Open Position$q$,$q$Open Position$q$,$q$Right hand to right hand hold. The lady turns under the arm with a clear spiral action; the man steps forward with a strong lead from the body.$q$),($q$Cha Cha$q$,$q$Spot Turns to L or R$q$,$q$Open Position$q$,$q$Open Position$q$,$q$Turning on the spot with hip action. The chasse is compact and the weight is on the ball of the foot; use the head to spot the turn.$q$),($q$Cha Cha$q$,$q$Time Steps (Basic in Place, Side Basic)$q$,$q$Closed Position$q$,$q$Closed Position$q$,$q$A rocking action with the weight changing on the ball of the foot. Keep the knees soft and use Cuban motion on the steps.$q$),($q$Rumba$q$,$q$Fan$q$,$q$Closed Position$q$,$q$Fan Position$q$,$q$The lady opens out to fan position while the man checks back with a stable posture. Hold the check for the full count with expression through the arms.$q$),($q$Rumba$q$,$q$Alemana$q$,$q$Open Position$q$,$q$Open Position$q$,$q$The lady turns under the man's raised hand in three steps. Slow-quick-quick-slow. Keep the connection through the hand and avoid pulling the lady's arm.$q$),($q$Rumba$q$,$q$Hockey Stick$q$,$q$Open Position$q$,$q$Open Position$q$,$q$A hockey stick shape created by the lady's line passing the man with a lock. The man guides rather than pushes; slow walks with delayed hip action.$q$),($q$Rumba$q$,$q$Natural Top$q$,$q$Closed Position$q$,$q$Closed Position$q$,$q$A spot turn to the right. The lady makes a full turn while the man stays compact and leads the turn from the body. Slow walks with Cuban motion between turns.$q$),($q$Rumba$q$,$q$Basic Movements (Closed, Open, In Place and Alternative)$q$,$q$Closed Position$q$,$q$Closed Position$q$,$q$Slow, quick, quick with delayed hip action. The weight must be fully transferred before the hip movement, with the knee straight on the standing leg and bent on the free leg.$q$),($q$Samba$q$,$q$Natural Roll$q$,$q$Closed Position$q$,$q$Closed Position$q$,$q$A rolling action with a travelling turn. Samba bounce action through the knees, with a rhythm of 1 a 2 and the weight remaining forward over the ball of the foot.$q$),($q$Samba$q$,$q$Closed Volta$q$,$q$Closed Position$q$,$q$Closed Position$q$,$q$A series of short steps on the balls of the feet with the knees together on the closes and a subtle bounce. Keep the body upright and the head still.$q$),($q$Samba$q$,$q$Bota Fogos To PP and CPP (Promenade Botafogos)$q$,$q$Promenade Position$q$,$q$Promenade Position$q$,$q$A forward step across with the free leg turned out, then a rocking action. Use a travelling action with soft knees; the hip action is smooth rather than sharp.$q$),($q$Samba$q$,$q$Whisk to Right and Left Underarm Turn (Volta Spot Turn to R and L for Lady)$q$,$q$Closed Position$q$,$q$Closed Position$q$,$q$The lady makes a volta spot turn under the man's raised arm. The man's whisk stays compact and led by the body, not the hand.$q$),($q$Jive$q$,$q$Basic in Place$q$,$q$Open Position$q$,$q$Open Position$q$,$q$Rock step and chasse with the bounce action in the knees. Weight on the ball of the foot; the feet stay close to the floor with quick, light movements.$q$),($q$Jive$q$,$q$Chicken Walks$q$,$q$Open Position$q$,$q$Open Position$q$,$q$Flicks of the free foot back and up with a rotation of the knees. The man stays low and relaxed; the flick is from the knee, not a kick.$q$),($q$Jive$q$,$q$Whip Throwaway$q$,$q$Open Position$q$,$q$Open Position$q$,$q$The man whips the lady into a throwaway; maintain a strong left hand connection and a compact rock before the throw. Rhythm Slow Slow Quick Quick Slow.$q$),($q$Paso Doble$q$,$q$Appel$q$,$q$Closed Position$q$,$q$Closed Position$q$,$q$A stamping action with the foot placed flat and sharp, ending in a strong, proud pose. Keep the weight over the supporting foot and the chest lifted.$q$),($q$Paso Doble$q$,$q$Sur Place$q$,$q$Closed Position$q$,$q$Closed Position$q$,$q$Marching in place with a strong, proud topline. The ribcage is lifted and the shoulders are down; keep the head high and the walk staccato.$q$),($q$Paso Doble$q$,$q$Separation$q$,$q$Closed Position$q$,$q$Open Position$q$,$q$The man and lady separate with Spanish lines. Keep the arms high with the elbows soft; stay visually connected through the eyes.$q$)) AS s(dance, name, sp, ep, notes) WHERE t.id = f.dance_type_id AND t.name = s.dance AND f.name = s.name AND f.notes = s.notes;
COMMIT;
